import 'package:flutter/material.dart';

/// Tema dari tokens.json kit "Minum Obat" (gaya modern).
/// Semua widget membaca warna/huruf/radius dari sini — tidak ada Color(0x..) di layar.
class Token {
  static const primer = Color(0xFF0E7490);
  static const primer2 = Color(0xFF155E75);
  static const aksen = Color(0xFFF97316);
  static const latar = Color(0xFFF7FBFC);
  static const permukaan = Color(0xFFFFFFFF);
  static const teks = Color(0xFF1A1A1A);
  static const teks2 = Color(0xFF5C5C66);
  static const garis = Color(0xFFE3E3E8);
  static const bahaya = Color(0xFFC8102E);
  static const radius = 12.0;
  static const fontJudul = 'Plus Jakarta Sans';
  static const fontIsi = 'Plus Jakarta Sans';
}

ThemeData buatTema() {
  final skema = ColorScheme.fromSeed(
    seedColor: Token.primer,
    brightness: Brightness.light,
  ).copyWith(
    primary: Token.primer,
    secondary: Token.aksen,
    surface: Token.latar,
    onSurface: Token.teks,
    onSurfaceVariant: Token.teks2,
    outline: Token.garis,
    error: Token.bahaya,
  );
  final bentuk = RoundedRectangleBorder(borderRadius: BorderRadius.circular(Token.radius));
  final dasar = ThemeData(useMaterial3: true, colorScheme: skema, fontFamily: Token.fontIsi);
  return dasar.copyWith(
    scaffoldBackgroundColor: Token.latar,
    textTheme: dasar.textTheme.copyWith(
      headlineMedium: dasar.textTheme.headlineMedium?.copyWith(fontFamily: Token.fontJudul, fontWeight: FontWeight.w700),
      titleLarge: dasar.textTheme.titleLarge?.copyWith(fontFamily: Token.fontJudul, fontWeight: FontWeight.w700),
    ),
    cardTheme: CardThemeData(
      elevation: 0,
      color: Token.permukaan,
      margin: EdgeInsets.zero,
      shape: bentuk.copyWith(side: const BorderSide(color: Token.garis)),
    ),
    filledButtonTheme: FilledButtonThemeData(style: FilledButton.styleFrom(minimumSize: const Size(64, 52), shape: bentuk)),
