    final awal = nama.replaceAll(RegExp(r'^(Halo|Hai|Mau ke mana),?\s*'), '').trim();
    return Row(children: [
      CircleAvatar(radius: 22, child: Text(awal.isEmpty ? '?' : awal[0])),
