import 'package:sehat_klinik/layar/antrean.dart';
import 'package:sehat_klinik/tema.dart';

Future<void> pasang(WidgetTester t, Widget layar, {double lebar = 360}) async {
  t.view.physicalSize = Size(lebar * 3, 800 * 3); // 360 × 800 dp pada 3x, sama dengan frame desain
  t.view.devicePixelRatio = 3;
  addTearDown(t.view.reset);
  await t.pumpWidget(MaterialApp(theme: buatTema(), home: layar));
}

void main() {
  group('LayarPilihJadwal', () {
    testWidgets('menampilkan isi utama sesuai desain', (t) async {
      await pasang(t, const LayarPilihJadwal());
      expect(find.text('Poli Penyakit Dalam'), findsWidgets);
    });
    testWidgets('tidak overflow di HP kecil 320 dp dan tablet 800 dp', (t) async {
      for (final lebar in [320.0, 800.0]) {
        await pasang(t, const LayarPilihJadwal(), lebar: lebar);
        expect(t.takeException(), isNull);
      }
    });
    testWidgets('lolos pedoman aksesibilitas', (t) async {
      final h = t.ensureSemantics();
      await pasang(t, const LayarPilihJadwal());
      await expectLater(t, meetsGuideline(androidTapTargetGuideline));
      await expectLater(t, meetsGuideline(labeledTapTargetGuideline));
      await expectLater(t, meetsGuideline(textContrastGuideline));
      h.dispose();
    });
    testWidgets('golden 360 × 800', (t) async {
      await pasang(t, const LayarPilihJadwal());
      await expectLater(find.byType(LayarPilihJadwal), matchesGoldenFile('goldens/pilih_jadwal.png'));
    }, tags: 'golden');
  });
  group('LayarAntrean', () {
    testWidgets('menampilkan isi utama sesuai desain', (t) async {
      await pasang(t, const LayarAntrean());
      expect(find.text('Antrean kamu'), findsWidgets);
    });
    testWidgets('tidak overflow di HP kecil 320 dp dan tablet 800 dp', (t) async {
      for (final lebar in [320.0, 800.0]) {
        await pasang(t, const LayarAntrean(), lebar: lebar);
        expect(t.takeException(), isNull);
      }
    });
    testWidgets('lolos pedoman aksesibilitas', (t) async {
      final h = t.ensureSemantics();
      await pasang(t, const LayarAntrean());
      await expectLater(t, meetsGuideline(androidTapTargetGuideline));
      await expectLater(t, meetsGuideline(labeledTapTargetGuideline));
      await expectLater(t, meetsGuideline(textContrastGuideline));
      h.dispose();
    });
    testWidgets('golden 360 × 800', (t) async {
      await pasang(t, const LayarAntrean());
      await expectLater(find.byType(LayarAntrean), matchesGoldenFile('goldens/antrean.png'));
    }, tags: 'golden');
  });
}

